223	function hex(color: number): string {
224	  return `#${color.toString(16).padStart(6, "0")}`;
225	}
226	
227	export class RestaurantArenaScene extends Phaser.Scene {
228	  private state: RestaurantArenaState;
229	  private onAction: (action: string) => void;
230	  /** Host-shell navigation — leaving to the menu, restarting the run — isn't a game action. */
231	  private onUi: (action: "menu" | "restart" | "help") => void;
232	  /** Which `state.lastOutcome.id` has already been shown, so a re-render mid-fade doesn't restart it. */
233	  private shownOutcomeId?: string;
234	  private outcomeToast?: { headline: string; tone: "safe" | "risky" | "neutral"; startedAt: number };
235	  private readonly outcomeToastMs = 2600;
236	  /** Rounds a design size into the pixel string Phaser wants. */
237	  private fs(px: number): string {
238	    return `${px}px`;
239	  }
240	
241	  /**
242	   * Phaser's canvas backing store matches CSS pixels, not device pixels, so
243	   * on any HiDPI screen the whole scene — vector shapes and text alike — is
244	   * drawn small and stretched up by the browser, which is what reads as
245	   * "blurry". The fix is a backing store `dpr`× the CSS size with the camera
246	   * zoomed to match: `mountRestaurantArenaScene` boots the game at
247	   * `cssSize * DPR`, and `cssWidth`/`cssHeight` below convert
248	   * `this.scale.width/height` (the backing store's pixel dimensions under
249	   * that scheme) back to the CSS-pixel units every layout call in this file
250	   * is authored in.
251	   *
252	   * An earlier attempt at this reliably painted the floor into a small
253	   * corner of the canvas instead of filling it once the backing store grew
254	   * past roughly one screen's worth of pixels, across every combination of
255	   * mutating a live game vs. booting fresh at the final size, and
256	   * `Scale.RESIZE` vs `Scale.NONE`. The actual cause: the game was booted at
257	   * the backing-store size, but `boot()` never multiplied its `width`/
258	   * `height` args by `dpr` before constructing `Phaser.Game` — so the
259	   * backing store stayed at 1× while the camera zoomed to `dpr`, which is
260	   * exactly the "zoomed into a corner" symptom (a `dpr`-zoomed camera
261	   * showing only `1/dpr` of a same-size backing store). Fixed by giving
262	   * `boot()` and this class the same `DPR` module constant instead of two
263	   * independent values that could disagree.
264	   */
265	  private readonly dpr = DPR;
266	
267	  /** `this.scale.width/height` in CSS-pixel units — see `dpr` above. */
268	  private get cssWidth(): number {
269	    return Math.round((this.scale.width || 520 * this.dpr) / this.dpr);
270	  }
271	  private get cssHeight(): number {
272	    return Math.round((this.scale.height || 300 * this.dpr) / this.dpr);
273	  }
274	  private workerStatuses = new Map<Role, RestaurantArenaWorkerStatus>();
275	  private readonly staffTokens = new Map<Role, Phaser.GameObjects.Container>();
276	
277	  constructor(
278	    state: RestaurantArenaState,
279	    onAction: (action: string) => void = () => {},
280	    onUi: (action: "menu" | "restart" | "help") => void = () => {},
281	    initialToastState?: OutcomeToastState,
282	  ) {
283	    super("restaurant-arena");
284	    this.state = state;
285	    this.onAction = onAction;
286	    this.onUi = onUi;
287	    const toastState = initOutcomeToastState(state.lastOutcome, initialToastState);
288	    this.shownOutcomeId = toastState.shownOutcomeId;
289	    this.outcomeToast = toastState.outcomeToast;
290	  }
291	
292	  getOutcomeToastState(): OutcomeToastState {
293	    return {
294	      shownOutcomeId: this.shownOutcomeId,
295	      outcomeToast: this.outcomeToast,
296	    };
297	  }
298	
299	  private staff(role: Role): { name: string; title: string; trait: string } {
300	    return this.state.staff?.[role] ?? DEFAULT_STAFF[role];
301	  }
302	
303	  private get running(): boolean {
304	    return Boolean(this.state.sim?.running);
305	  }
306	
307	  // ── Interaction primitives ───────────────────────────────────────────
308	
309	  /**
310	   * Turn a region into a control. Everything the player can do is a thing
311	   * on the floor — there is no key strip under the canvas — so each one has
312	   * to announce itself on hover and say what it does.
313	   */
314	  private hotspot(rect: ArenaRect, action: string, tip?: string, depth = 5, dispatch?: (action: string) => void): Phaser.GameObjects.Rectangle {
315	    const zone = this.add.rectangle(rect.x, rect.y, rect.width, rect.height, 0xffffff, 0.001).setOrigin(0, 0);
316	    zone.setInteractive({ useHandCursor: true });
317	    zone.setDepth(depth);
318	    const halo = this.add.rectangle(rect.x, rect.y, rect.width, rect.height).setOrigin(0, 0);
319	    halo.setStrokeStyle(2, COLORS.pass, 0.95);
320	    halo.setDepth(depth);
321	    halo.setVisible(false);
322	    zone.on("pointerover", () => {
323	      halo.setVisible(true);
324	    });
325	    zone.on("pointerout", () => {
326	      halo.setVisible(false);
327	    });
328	    zone.on("pointerdown", () => {
329	      (dispatch ?? this.onAction)(action);
330	    });
331	    return zone;
332	  }
333	
334	  /** A pill button drawn on the canvas: the only kind of button this game has. */
335	  private button(
336	    rect: ArenaRect,
337	    label: string,
338	    action: string,
339	    opts: { fill?: number; text?: string; size?: number; tip?: string; depth?: number; dispatch?: (action: string) => void } = {},
340	  ): void {
341	    const depth = opts.depth ?? 6;
342	    const bg = this.add.rectangle(rect.x, rect.y, rect.width, rect.height, opts.fill ?? 0x4a3a2c).setOrigin(0, 0);
343	    bg.setStrokeStyle(1, COLORS.cream, 0.35);
344	    bg.setDepth(depth);
345	    const text = this.add
346	      .text(rect.x + rect.width / 2, rect.y + rect.height / 2, label, {
347	        color: opts.text ?? "#fff3d6",
348	        fontFamily: MONO,
349	        fontSize: this.fs(opts.size ?? 9),
350	        fontStyle: "bold",
351	      })
352	      .setOrigin(0.5)
353	      .setDepth(depth + 1);
354	    const zone = this.hotspot(rect, action, opts.tip, depth + 2, opts.dispatch);
355	    zone.on("pointerover", () => bg.setFillStyle(Phaser.Display.Color.ValueToColor(opts.fill ?? 0x4a3a2c).lighten(18).color));
356	    zone.on("pointerout", () => bg.setFillStyle(opts.fill ?? 0x4a3a2c));
