742	  private drawDining(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
743	    const zone = layout.dining;
744	    const compact = layout.compact;
745	    this.zonePanel(g, zone, COLORS.dining, "DINING", compact);
746	
747	    const tables = this.state.tables.slice(0, 4);
748	    const top = zone.y + (compact ? 15 : 19);
749	    const available = Math.max(24, zone.height - (top - zone.y) - 4);
750	    const cols = tables.length > 2 ? 2 : tables.length || 1;
751	    const rows = Math.ceil(tables.length / cols) || 1;
752	
753	    tables.forEach((table, index) => {
754	      const col = index % cols;
755	      const row = Math.floor(index / cols);
756	      const cx = zone.x + (zone.width * (col + 0.5)) / cols;
757	      const cy = top + (available * (row + 0.5)) / rows;
758	      // Capped at a fixed 18px, tables read as a sparse handful of dots on a
759	      // real desktop window where this zone is much bigger than a 520px
760	      // canvas — let them grow with the room, not just with the cell they
761	      // have to fit in.
762	      const fitsCell = Math.min(zone.width / cols, available / rows) * 0.3;
763	      const styleCap = compact ? 13 : Math.min(32, 18 + Math.max(0, zone.width - 360) * 0.03);
764	      const radius = Math.max(8, Math.min(styleCap, fitsCell));
765	
766	      // Chairs first so the table top sits over them.
767	      const seats = Math.min(table.seats, 4);
768	      for (let seat = 0; seat < seats; seat++) {
769	        const angle = (Math.PI * 2 * seat) / seats - Math.PI / 2;
770	        g.fillStyle(0x8a5a34);
771	        g.fillCircle(cx + Math.cos(angle) * (radius + 5), cy + Math.sin(angle) * (radius + 5), compact ? 2.5 : 3.5);
772	      }
773	      g.fillStyle(table.status === "occupied" ? COLORS.occupied : COLORS.empty);
774	      g.fillCircle(cx, cy, radius);
775	      g.lineStyle(2, COLORS.cream, 0.85);
776	      g.strokeCircle(cx, cy, radius);
777	
778	      const order = this.state.orders.find((o) => o.tableId === table.id && o.status !== "served" && o.status !== "cancelled");
779	      this.add
780	        .text(cx, cy, table.id.replace("table-", "T"), {
781	          color: "#ffffff",
782	          fontFamily: MONO,
783	          fontSize: compact ? this.fs(7) : this.fs(9),
784	          fontStyle: "bold",
785	        })
786	        .setOrigin(0.5);
787	
788	      if (order) {
789	        // A plate icon on the table once the food is up, so the floor shows
790	        // what the ticket rail says.
791	        if (order.status === "ready") {
792	          g.fillStyle(0xfff8e7);
793	          g.fillCircle(cx + radius * 0.7, cy - radius * 0.7, compact ? 3 : 4);
794	        }
795	        if (order.allergy) {
796	          this.add
797	            .text(cx, cy - radius - (compact ? 6 : 8), "!", {
798	              color: "#ffffff",
799	              backgroundColor: "#c73535",
800	              fontFamily: MONO,
801	              fontSize: compact ? this.fs(6) : this.fs(8),
802	              fontStyle: "bold",
803	              padding: { x: 3, y: 0 },
804	            })
805	            .setOrigin(0.5);
806	        }
807	        const index3 = Number((table.id.match(/\d+/) ?? ["0"])[0]);
808	        if (index3 >= 1 && index3 <= 3 && order.priority !== "high") {
809	          this.hotspot(
810	            { x: cx - radius - 4, y: cy - radius - 4, width: radius * 2 + 8, height: radius * 2 + 8 },
811	            `rush_table_${index3}`,
812	            `Rush ${table.id.replace("table-", "table ")}`,
813	          );
814	        }
815	      }
816	    });
817	  }
