1726	export function mountRestaurantArenaScene(
1727	  parent: HTMLElement,
1728	  state: RestaurantArenaState,
1729	  onAction: (action: string) => void = () => {},
1730	  onUi: (action: "menu" | "restart" | "help") => void = () => {},
1731	): RestaurantArenaSceneHandle {
1732	  // Calling `game.scale.resize()` on a live game — at any point after
1733	  // construction, however long after, `Core.Events.READY` or not — reliably
1734	  // corrupts a framebuffer ("Framebuffer status: Incomplete Attachment") and
1735	  // leaves the canvas permanently blank in this renderer. So a genuine
1736	  // resize never calls `.resize()` on an existing game: it tears the game
1737	  // down and boots a fresh one at the new size instead — cheap, since this
1738	  // scene already repaints itself from scratch on every state change.
1739	  //
1740	  // `width`/`height` passed to `boot()` below are CSS pixels; `bootedWidth`/
1741	  // `bootedHeight` (compared against `parent`'s real box everywhere else in
1742	  // this function) track those CSS-pixel values. The `Phaser.Game` config
1743	  // gets them multiplied by `DPR` instead, so the backing store is the
1744	  // supersampled size `RestaurantArenaScene.dpr`'s camera zoom expects — see
1745	  // that field's comment for what goes wrong when this multiplier and the
1746	  // scene's own `dpr` disagree.
1747	  let game: Phaser.Game | undefined;
1748	  let scene: RestaurantArenaScene | undefined;
1749	  let destroyed = false;
1750	  let currentState = state;
1751	  let bootedWidth = 0;
1752	  let bootedHeight = 0;
1753	  let persistedToastState: OutcomeToastState | undefined;
1754	
1755	  const teardown = () => {
1756	    if (scene) {
1757	      persistedToastState = scene.getOutcomeToastState();
1758	    }
1759	    game?.destroy(true);
1760	    game = undefined;
1761	    scene = undefined;
1762	  };
1763	
1764	  const boot = (width: number, height: number) => {
1765	    if (destroyed) return;
1766	    if (game) return;
1767	    bootedWidth = width;
1768	    bootedHeight = height;
1769	    scene = new RestaurantArenaScene(currentState, onAction, onUi, persistedToastState);
1770	    game = new Phaser.Game({
1771	      type: Phaser.AUTO,
1772	      parent,
1773	      width: Math.round(width * DPR),
1774	      height: Math.round(height * DPR),
1775	      backgroundColor: COLORS.ink,
1776	      scene,
1777	      // NONE, not RESIZE: this game is never resized in place (see the
1778	      // teardown-and-reboot comment above) — Phaser doesn't need to watch
1779	      // for size changes of its own.
1780	      scale: { mode: Phaser.Scale.NONE },
1781	    });
1782	    scheduleVerification();
1783	  };
