1785	  const reboot = (width: number, height: number) => {
1786	    if (destroyed || !parent.isConnected) return;
1787	    if (width <= 0 || height <= 0) return;
1788	    if (game && width === bootedWidth && height === bootedHeight) return;
1789	    teardown();
1790	    boot(width, height);
1791	  };
1792	
1793	  /**
1794	   * A cold start (a just-restarted dev server, a slow initial layout pass
1795	   * on a big window) can settle to its *true* box later than either the
1796	   * boot-time measurement below or this module's own `ResizeObserver`
1797	   * happened to catch — both can agree on the same too-small intermediate
1798	   * reading and never see a further "resize" to correct it from, since
1799	   * nothing about `parent` actually changes again afterward from the
1800	   * browser's point of view. A few delayed re-checks against the real box,
1801	   * independent of any resize *event*, catch that without needing one.
1802	   */
1803	  const scheduleVerification = () => {
1804	    for (const delay of [300, 1000, 3000]) {
1805	      setTimeout(() => {
1806	        if (destroyed || !parent.isConnected) return;
1807	        const rect = parent.getBoundingClientRect();
1808	        reboot(Math.round(rect.width), Math.round(rect.height));
1809	      }, delay);
1810	    }
1811	  };
1812	
1813	  // `getBoundingClientRect()` called the instant we're handed `parent` can
1814	  // still read stale/zero — the caller may have just set `innerHTML` and
1815	  // not yet given the browser a layout pass. ResizeObserver is the primary
1816	  // boot path; rAF polling is a backup for browsers where the first RO
1817	  // callback still arrives before layout settles.
1818	  let attempts = 0;
1819	  const tryBoot = () => {
1820	    if (destroyed || game) return;
1821	    const rect = parent.getBoundingClientRect();
1822	    if (rect.width > 64 && rect.height > 64) {
1823	      boot(Math.round(rect.width), Math.round(rect.height));
1824	      return;
1825	    }
1826	    attempts += 1;
1827	    if (attempts < 30) {
1828	      requestAnimationFrame(tryBoot);
1829	    }
1830	  };
1831	
1832	  let resizeTimer: ReturnType<typeof setTimeout> | undefined;
1833	  const observer =
1834	    typeof ResizeObserver !== "undefined"
1835	      ? new ResizeObserver((entries) => {
1836	          const rect = entries[0]?.contentRect;
1837	          if (!rect || rect.width <= 0 || rect.height <= 0) return;
1838	          const width = Math.round(rect.width);
1839	          const height = Math.round(rect.height);
1840	          if (!game) {
1841	            boot(width, height);
1842	            return;
1843	          }
1844	          if (width === bootedWidth && height === bootedHeight) return;
1845	          if (resizeTimer !== undefined) clearTimeout(resizeTimer);
1846	          resizeTimer = setTimeout(() => {
1847	            resizeTimer = undefined;
1848	            reboot(width, height);
1849	          }, 150);
1850	        })
1851	      : undefined;
1852	  observer?.observe(parent);
1853	  requestAnimationFrame(tryBoot);
1854	
1855	  return {
1856	    render: (next) => {
1857	      currentState = next;
1858	      scene?.setState(next);
1859	      if (scene) {
1860	        persistedToastState = scene.getOutcomeToastState();
1861	      }
1862	    },
1863	    setWorkerStatus: (role, status) => scene?.setWorkerStatus(role, status),
1864	    destroy: () => {
1865	      destroyed = true;
1866	      if (resizeTimer !== undefined) clearTimeout(resizeTimer);
1867	      observer?.disconnect();
1868	      teardown();
1869	    },
1870	  };
1871	}
