/**
 * Where every part of the Restaurant Arena floor goes, for a given canvas.
 *
 * The scene is authored in CSS-pixel units against one baseline window —
 * 520×740, the size the overlay opens at — and then *grows* from it. Growing
 * is the whole point of this module living on its own: a 1500×1000 desktop
 * window used to get the same 38px top bar and the same 9px labels as a phone,
 * so the floor read as a postage stamp of UI marooned in a big dark room. Every
 * band, zone and gap below is a baseline size multiplied by `scale`, and the
 * scene multiplies its font sizes by the same number, so the whole thing keeps
 * its proportions instead of stretching only in the directions that happen to
 * be free.
 *
 * Two hard rules the arithmetic here has to keep, because callers rely on them:
 *
 * 1. Every rect returned fits inside `width`×`height`. Rows are allocated out
 *    of the space that is actually available (fractional caps, not just
 *    preferred pixel sizes), so a short window shrinks its bands rather than
 *    pushing the ticket rail off the bottom edge.
 * 2. `spineY` — the hallway line staff walk along, see `staff-walk.ts` — runs
 *    through the pass zone. The pass is the doorway between the kitchen and
 *    the dining room, so the one horizontal line every walk rides has to cross
 *    it.
 */

export type ArenaRect = { x: number; y: number; width: number; height: number };
export type ArenaPoint = { x: number; y: number };
export type ArenaLocation = "floor" | "kitchen" | "pass" | "queue";

export interface RestaurantArenaLayout {
  /** Small window: tighter padding, and text stops growing. */
  compact: boolean;
  /** Multiplier for every authored size, 1 at the baseline window. */
  scale: number;
  /** Wide window: the event feed rides beside the floor instead of under it. */
  feedBeside: boolean;
  topBar: ArenaRect;
  brief: ArenaRect;
  kitchen: ArenaRect;
  pass: ArenaRect;
  dining: ArenaRect;
  door: ArenaRect;
  doorStand: ArenaRect;
  waypoints: Record<ArenaLocation, ArenaPoint>;
  /** Y coordinate of the hallway line that runs through the pass zone. */
  spineY: number;
  tickets: ArenaRect;
  feed: ArenaRect;
}

/** The window the scene's sizes are authored against: `scale` is 1 here. */
export const BASE_WIDTH = 520;
export const BASE_HEIGHT = 740;
/**
 * Past roughly 2× the baseline the floor stops gaining anything from more
 * pixels — tables and staff just get chunky — so growth stops a little short
 * of that.
 */
export const MAX_SCALE = 1.9;
/** Under either of these the layout is cramped enough to need compact mode. */
export const COMPACT_WIDTH = 460;
export const COMPACT_HEIGHT = 420;
/** From here up there is room for a floor *and* a feed rail side by side. */
export const FEED_BESIDE_WIDTH = 600;
/**
 * The host stand is a click target with two lines of text on it, so it has a
 * floor it never goes below however little room the door zone has.
 */
export const MIN_STAND_WIDTH = 56;
export const MIN_STAND_HEIGHT = 22;

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/**
 * The growth factor for a window: 1 at the baseline, rising with whichever
 * axis has the *least* room to spare (growing text on the strength of a wide
 * window that is only 400px tall just pushes the bands off the bottom), and
 * never above `MAX_SCALE`. Compact windows stay at 1 — below that size the
 * problem is fitting the UI at all, not that it reads too small.
 */
export function arenaScale(width: number, height: number, compact: boolean): number {
  if (compact) return 1;
  return clamp(Math.min(width / BASE_WIDTH, height / BASE_HEIGHT), 1, MAX_SCALE);
}

export function restaurantArenaLayout(width: number, height: number): RestaurantArenaLayout {
  const w = Math.max(1, Math.round(width));
  const h = Math.max(1, Math.round(height));

  const compact = w < COMPACT_WIDTH || h < COMPACT_HEIGHT;
  const scale = arenaScale(w, h, compact);
  const feedBeside = w >= FEED_BESIDE_WIDTH;
  const s = (px: number) => Math.round(px * scale);

  // Margins and gaps come out of the window first, and are capped against it
  // so that even an absurd canvas leaves a positive content box behind.
  const margin = Math.max(0, Math.min(s(compact ? 5 : 8), Math.floor((w - 1) / 4), Math.floor((h - 1) / 4)));
  const availWidth = w - margin * 2;
  const availHeight = h - margin * 2;

  // Rows: top bar, brief, floor, ticket rail, and — unless it sits beside the
  // floor — the feed. The floor takes whatever the other rows leave, and the
  // fractional caps below (which sum to 0.66) are what guarantee it a share.
  const rowGaps = feedBeside ? 3 : 4;
  const gap = Math.max(0, Math.min(s(compact ? 4 : 6), Math.floor((availHeight * 0.15) / rowGaps)));
  const bodyHeight = availHeight - gap * rowGaps;

  const topBarHeight = Math.min(s(38), Math.floor(bodyHeight * 0.12));
  const briefHeight = Math.min(s(32), Math.floor(bodyHeight * 0.1));
  const ticketsHeight = Math.min(s(72), Math.floor(bodyHeight * 0.16));
  const stackedFeedHeight = feedBeside
    ? 0
    : Math.min(Math.max(s(110), Math.round(h * 0.2)), Math.floor(bodyHeight * 0.28));
  const floorHeight = bodyHeight - topBarHeight - briefHeight - ticketsHeight - stackedFeedHeight;

  const feedWidth = feedBeside ? Math.min(s(190), Math.floor(availWidth * 0.34)) : availWidth;
  const floorWidth = feedBeside ? Math.max(1, availWidth - feedWidth - gap) : availWidth;

  const topBar = { x: margin, y: margin, width: availWidth, height: topBarHeight };
  const briefY = topBar.y + topBarHeight + gap;
  const brief = { x: margin, y: briefY, width: availWidth, height: briefHeight };
  const bodyY = briefY + briefHeight + gap;

  // Kitchen | pass | (dining over door). The caps keep the dining room the
  // biggest thing on the floor no matter how the percentages round.
  const kitchenWidth = Math.min(Math.round(floorWidth * 0.25), Math.floor(floorWidth * 0.3));
  const passWidth = Math.min(Math.max(s(24), Math.round(floorWidth * 0.07)), Math.floor(floorWidth * 0.12));
  const kitchen = { x: margin, y: bodyY, width: Math.max(1, kitchenWidth), height: floorHeight };
  const pass = { x: kitchen.x + kitchen.width + gap, y: bodyY, width: Math.max(1, passWidth), height: floorHeight };

  const diningX = pass.x + pass.width + gap;
  const diningWidth = Math.max(1, margin + floorWidth - diningX);
  // The door band is the bottom slice of the dining column, capped under half
  // of it so the hallway line (the floor's mid-line) stays in the dining room
  // rather than landing in the doorway.
  const floorGap = Math.min(gap, Math.max(0, floorHeight - 2));
  const splitRoom = Math.max(0, floorHeight - floorGap);
  const doorHeight = Math.min(Math.max(s(56), Math.round(floorHeight * 0.28)), Math.floor(splitRoom * 0.45));
  const diningHeight = Math.max(0, splitRoom - doorHeight);
  const dining = { x: diningX, y: bodyY, width: diningWidth, height: diningHeight };
  const door = { x: diningX, y: bodyY + diningHeight + floorGap, width: diningWidth, height: doorHeight };

  // The host stand: a real slab in the door zone, never smaller than a
  // two-line click target, and kept on-canvas when the door zone itself is
  // too small to hold one.
  const labelHeight = s(14);
  const standWidth = Math.min(Math.max(MIN_STAND_WIDTH, s(56), Math.round(door.width * 0.36)), Math.max(MIN_STAND_WIDTH, s(90)));
  const standHeight = Math.max(MIN_STAND_HEIGHT, Math.min(s(36), door.height - labelHeight - s(4)));
  const doorStand = {
    x: Math.max(0, Math.min(door.x + Math.min(s(40), Math.max(0, door.width - standWidth)), w - margin - standWidth)),
    y: Math.max(0, Math.min(door.y + Math.min(labelHeight, Math.max(0, door.height - standHeight)), h - margin - standHeight)),
    width: standWidth,
    height: standHeight,
  };

  // One horizontal line through the middle of the floor. Kitchen and pass are
  // full-height, so their centres already sit on it — which is what makes a
  // kitchen→pass walk a straight line down the hallway rather than a diagonal
  // across two rooms.
  const spineY = Math.round(pass.y + pass.height / 2);
  const waypoints: Record<ArenaLocation, ArenaPoint> = {
    kitchen: { x: Math.round(kitchen.x + kitchen.width / 2), y: spineY },
    pass: { x: Math.round(pass.x + pass.width / 2), y: spineY },
    floor: { x: Math.round(dining.x + dining.width / 2), y: Math.round(dining.y + dining.height / 2) },
    queue: {
      x: Math.round(doorStand.x + doorStand.width / 2),
      y: Math.round(doorStand.y + doorStand.height / 2),
    },
  };

  const tickets = { x: margin, y: bodyY + floorHeight + gap, width: floorWidth, height: ticketsHeight };
  const feed = feedBeside
    ? {
        x: margin + floorWidth + gap,
        y: bodyY,
        width: feedWidth,
        height: floorHeight + gap + ticketsHeight,
      }
    : { x: margin, y: tickets.y + ticketsHeight + gap, width: availWidth, height: stackedFeedHeight };

  return {
    compact,
    scale,
    feedBeside,
    topBar,
    brief,
    kitchen,
    pass,
    dining,
    door,
    doorStand,
    waypoints,
    spineY,
    tickets,
    feed,
  };
}

