/**
 * Staff walking the floor.
 *
 * Four stations — kitchen, pass, dining floor, door queue — wired as one
 * hallway rather than a fully connected set:
 *
 *     kitchen ── pass ── floor ── queue
 *
 * Nothing is adjacent to everything, on purpose. The pass and the floor are
 * *through-stations*: a cook sent from the line to the door has to cross the
 * pass and then the dining room to get there, which is exactly what makes
 * pulling someone off station cost time the player can see. The engine's
 * `assign_<role>_<location>` action is instant; this is the part that makes it
 * legible.
 *
 * Walks ride a single horizontal hallway line (`spineY`, from
 * `restaurant-arena-layout.ts`, which runs through the pass zone) instead of
 * cutting corner-to-corner: staff step out of a room onto the hallway, travel
 * along it, and step into the destination. Every segment is axis-aligned, so
 * nobody ever walks diagonally through a wall or across the middle of a table.
 */

import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";

export type WalkNode = ArenaLocation;
export type Point = ArenaPoint;

export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
  kitchen: ["pass"],
  pass: ["kitchen", "floor"],
  floor: ["pass", "queue"],
  queue: ["floor"],
};

/** A walking pace, not a running one: fast enough to be worth doing, slow
 *  enough that a bad assignment is visibly expensive. */
export const WALK_SPEED_PX_PER_SEC = 200;

/** Below this many pixels two points count as the same place. */
const EPSILON = 0.01;

/**
 * The stations to visit, in order, walking `from` to `to` along the hallway —
 * including `from` itself, so the result reads as a whole route and
 * `bfsPath(x, x)` is the one-element route that stays put.
 */
export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
  if (from === to) return [from];
  const previous = new Map<WalkNode, WalkNode>();
  const seen = new Set<WalkNode>([from]);
  const queue: WalkNode[] = [from];

  while (queue.length > 0) {
    const node = queue.shift()!;
    for (const next of WALK_GRAPH[node] ?? []) {
      if (seen.has(next)) continue;
      seen.add(next);
      previous.set(next, node);
      if (next === to) {
        const path: WalkNode[] = [to];
        let step: WalkNode | undefined = to;
        while (step !== undefined && step !== from) {
          step = previous.get(step);
          if (step !== undefined) path.unshift(step);
        }
        return path;
      }
      queue.push(next);
    }
  }
  // Unreachable with WALK_GRAPH as wired, but a caller passing a node that
  // isn't on the hallway should get "stay where you are", not a crash.
  return [from];
}

/**
 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
 * hallway instead of cutting diagonally through a room.
 *
 * Each leg is at most three axis-aligned moves: out of the room onto the
 * hallway, along the hallway, then into the destination. Moves that would
 * cover no distance are dropped, so a walk that is already on the hallway
 * doesn't emit a point where it already stands.
 */
export function corridorPoints(
  start: Point,
  nodes: readonly WalkNode[],
  waypoints: Record<WalkNode, Point>,
  spineY: number,
): Point[] {
  const points: Point[] = [];
  let cursor: Point = { x: start.x, y: start.y };

  const advance = (point: Point) => {
    if (Math.abs(point.x - cursor.x) < EPSILON && Math.abs(point.y - cursor.y) < EPSILON) return;
    points.push(point);
    cursor = point;
  };

  for (const node of nodes) {
    const destination = waypoints[node];
    if (!destination) continue;
    advance({ x: cursor.x, y: spineY });
    advance({ x: destination.x, y: spineY });
    advance({ x: destination.x, y: destination.y });
  }
  return points;
}

/** Duration of a single straight hop between two points, at WALK_SPEED_PX_PER_SEC. */
export function hopDurationMs(from: Point, to: Point): number {
  const distance = Math.hypot(to.x - from.x, to.y - from.y);
  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
}

/** Eased so each hop starts and lands softly — a person, not a slider. */
function ease(t: number): number {
  return t < 0.5 ? 2 * t * t : 1 - ((1 - t) * (1 - t) * 2);
}

/**
 * One member of staff, mid-walk. Owns its own pixel position across repaints:
 * the scene rebuilds every game object on every state change, so if the walk
 * lived on the token it would restart from the destination each tick. The
 * scene keeps one of these per role for the lifetime of the scene and reads
 * `x`/`y` off it when it draws.
 */
export class StaffWalker {
  x: number;
  y: number;
  facing: 1 | -1 = 1;
  walking = false;
  /** Set while the player has the token under the pointer: the drag owns the
   *  position, so `step()` keeps its hands off it. */
  dragging = false;
  /** The station this walker belongs to — its destination while walking. */
  node: WalkNode;

  /** Where the walk is routing *from*. Only reaches `node` on arrival, so a
   *  target changed mid-hallway re-routes from the last station actually
   *  reached rather than from one the walker never got to. */
  private origin: WalkNode;
  private queue: Point[] = [];
  private hopFrom: Point;
  private hopTo?: Point;
  private hopMs = 0;
  private hopElapsed = 0;

  constructor(node: WalkNode, slot: Point) {
    this.node = node;
    this.origin = node;
    this.x = slot.x;
    this.y = slot.y;
    this.hopFrom = { x: slot.x, y: slot.y };
  }

  /** Teleport onto `slot`/`node` with no walk in progress (e.g. after a drag drop). */
  snap(slot: Point, node: WalkNode): void {
    this.x = slot.x;
    this.y = slot.y;
    this.node = node;
    this.origin = node;
    this.queue = [];
    this.hopFrom = { x: slot.x, y: slot.y };
    this.hopTo = undefined;
    this.hopMs = 0;
    this.hopElapsed = 0;
    this.walking = false;
  }

  /** Walk toward `target` from the current pixel, along the hallway at `spineY`. */
  setTarget(target: WalkNode, waypoints: Record<WalkNode, Point>, spineY: number): void {
    this.node = target;
    this.queue = corridorPoints({ x: this.x, y: this.y }, bfsPath(this.origin, target), waypoints, spineY);
    this.hopTo = undefined;
    this.walking = this.queue.length > 0;
    if (!this.walking) {
      this.origin = target;
      return;
    }
    this.nextHop();
  }

  /** Advance the walk by `dtMs` at simulation `speed` (0 pauses). Returns
   *  whether the pixel position changed. */
  step(dtMs: number, speed: number): boolean {
    if (this.dragging || !this.walking) return false;
    let budget = dtMs * speed;
    if (!(budget > 0)) return false;

    const wasX = this.x;
    const wasY = this.y;
    while (budget > 0 && this.hopTo) {
      const hop = this.hopTo;
      if (this.hopMs <= 0) {
        this.x = hop.x;
        this.y = hop.y;
        this.nextHop();
        continue;
      }
      const used = Math.min(budget, this.hopMs - this.hopElapsed);
      this.hopElapsed += used;
      budget -= used;
      if (this.hopElapsed >= this.hopMs) {
        this.x = hop.x;
        this.y = hop.y;
        this.nextHop();
        continue;
      }
      const eased = ease(this.hopElapsed / this.hopMs);
      this.x = this.hopFrom.x + (hop.x - this.hopFrom.x) * eased;
      this.y = this.hopFrom.y + (hop.y - this.hopFrom.y) * eased;
    }
    return this.x !== wasX || this.y !== wasY;
  }

  private nextHop(): void {
    const next = this.queue.shift();
    if (!next) {
      this.hopTo = undefined;
      this.hopMs = 0;
      this.hopElapsed = 0;
      this.walking = false;
      this.origin = this.node;
      return;
    }
    this.hopFrom = { x: this.x, y: this.y };
    this.hopTo = next;
    this.hopMs = hopDurationMs(this.hopFrom, next);
    this.hopElapsed = 0;
    if (Math.abs(next.x - this.hopFrom.x) > EPSILON) this.facing = next.x > this.hopFrom.x ? 1 : -1;
  }
}

