/**
 * Holds repaints back for the length of a drag.
 *
 * The arena scene repaints from scratch on every state change — it destroys
 * every game object and builds new ones — which is fine sixty times a second
 * until the player is *holding* one of those objects. A tick landing mid-drag
 * used to destroy the token under the pointer, so the drag died silently and
 * the worker snapped back to their old station: dragging staff was unusable on
 * a running clock, which is the only clock it matters on.
 *
 * So: while a drag is open, a paint request is recorded rather than performed,
 * and replayed once — however many were asked for — when the drag ends. A
 * resize is the exception: it rebuilds the scene at the new size anyway, so it
 * drops the drag and forgets anything owed, and the `dragend` that arrives
 * afterwards from the pointer release owes nothing.
 */
export class RepaintGate {
  private dragging = false;
  private owed = false;

  /** True while a drag is open (between beginDrag() and endDrag()/resize()). */
  get isDragging(): boolean {
    return this.dragging;
  }

  beginDrag(): void {
    this.dragging = true;
  }

  /** Paints immediately (returns true) unless a drag is open, in which case
   *  the paint is held back (returns false) and one repaint becomes owed. */
  requestPaint(): boolean {
    if (this.dragging) {
      this.owed = true;
      return false;
    }
    return true;
  }

  /** Ends the drag. Returns whether a repaint was held back during it
   *  (and thus needs to be replayed by the caller now). */
  endDrag(): boolean {
    const owed = this.owed;
    this.dragging = false;
    this.owed = false;
    return owed;
  }

  /** Drops any open drag and clears anything owed, since the resize itself
   *  repaints from scratch. */
  resize(): void {
    this.dragging = false;
    this.owed = false;
  }
}

