import { describe, expect, test } from "bun:test";
import {
  BASE_HEIGHT,
  BASE_WIDTH,
  COMPACT_HEIGHT,
  COMPACT_WIDTH,
  FEED_BESIDE_WIDTH,
  MAX_SCALE,
  MIN_STAND_HEIGHT,
  MIN_STAND_WIDTH,
  restaurantArenaLayout,
  type ArenaRect,
  type RestaurantArenaLayout,
} from "./restaurant-arena-layout.js";

const SIZES: [number, number][] = [
  [320, 240],
  [380, 400],
  [460, 420],
  [BASE_WIDTH, BASE_HEIGHT],
  [600, 700],
  [900, 800],
  [1280, 900],
  [1920, 1200],
  [2400, 2400],
  [1500, 380],
  [380, 1500],
];

function rects(layout: RestaurantArenaLayout): [string, ArenaRect][] {
  return [
    ["topBar", layout.topBar],
    ["brief", layout.brief],
    ["kitchen", layout.kitchen],
    ["pass", layout.pass],
    ["dining", layout.dining],
    ["door", layout.door],
    ["doorStand", layout.doorStand],
    ["tickets", layout.tickets],
    ["feed", layout.feed],
  ];
}

describe("restaurantArenaLayout", () => {
  test("fits every rect inside the canvas at every size", () => {
    for (const [width, height] of SIZES) {
      const layout = restaurantArenaLayout(width, height);
      for (const [name, rect] of rects(layout)) {
        const where = `${name} at ${width}x${height}`;
        expect(rect.x, where).toBeGreaterThanOrEqual(0);
        expect(rect.y, where).toBeGreaterThanOrEqual(0);
        expect(rect.width, where).toBeGreaterThanOrEqual(0);
        expect(rect.height, where).toBeGreaterThanOrEqual(0);
        expect(rect.x + rect.width, where).toBeLessThanOrEqual(width);
        expect(rect.y + rect.height, where).toBeLessThanOrEqual(height);
      }
    }
  });

  test("scale is 1 at the baseline window", () => {
    expect(restaurantArenaLayout(BASE_WIDTH, BASE_HEIGHT).scale).toBe(1);
  });

  test("grows with the smaller of the two axes, and never past the cap", () => {
    // Wide but baseline-tall: the short axis holds it at 1.
    expect(restaurantArenaLayout(1600, BASE_HEIGHT).scale).toBe(1);
    // Both axes 1.5x: grows.
    const grown = restaurantArenaLayout(BASE_WIDTH * 1.5, BASE_HEIGHT * 1.5);
    expect(grown.scale).toBeCloseTo(1.5, 5);
    // Never below 1, and never above the cap.
    for (const [width, height] of SIZES) {
      const { scale } = restaurantArenaLayout(width, height);
      expect(scale).toBeGreaterThanOrEqual(1);
      expect(scale).toBeLessThanOrEqual(MAX_SCALE);
    }
    expect(restaurantArenaLayout(4000, 4000).scale).toBe(MAX_SCALE);
  });

  test("bands and text grow with the window", () => {
    const base = restaurantArenaLayout(BASE_WIDTH, BASE_HEIGHT);
    const big = restaurantArenaLayout(BASE_WIDTH * 2, BASE_HEIGHT * 2);
    expect(big.scale).toBeGreaterThan(base.scale);
    expect(big.topBar.height).toBeGreaterThan(base.topBar.height);
    expect(big.brief.height).toBeGreaterThan(base.brief.height);
    expect(big.tickets.height).toBeGreaterThan(base.tickets.height);
  });

  test("stays compact and stops growing text on a small window", () => {
    expect(restaurantArenaLayout(COMPACT_WIDTH - 1, 900).compact).toBe(true);
    expect(restaurantArenaLayout(900, COMPACT_HEIGHT - 1).compact).toBe(true);
    expect(restaurantArenaLayout(COMPACT_WIDTH - 1, 4000).scale).toBe(1);
    expect(restaurantArenaLayout(4000, COMPACT_HEIGHT - 1).scale).toBe(1);
    expect(restaurantArenaLayout(BASE_WIDTH, BASE_HEIGHT).compact).toBe(false);
  });

  test("puts the feed beside the floor only once the window is wide enough", () => {
    expect(restaurantArenaLayout(FEED_BESIDE_WIDTH - 1, 800).feedBeside).toBe(false);
    expect(restaurantArenaLayout(FEED_BESIDE_WIDTH, 800).feedBeside).toBe(true);

    const beside = restaurantArenaLayout(1200, 800);
    expect(beside.feedBeside).toBe(true);
    // Beside means: to the right of the floor, not under it.
    expect(beside.feed.x).toBeGreaterThanOrEqual(beside.dining.x + beside.dining.width);
    expect(beside.feed.y).toBeLessThan(beside.tickets.y);
    expect(beside.feed.height).toBeGreaterThan(beside.tickets.height);

    const stacked = restaurantArenaLayout(520, 800);
    expect(stacked.feedBeside).toBe(false);
    expect(stacked.feed.y).toBeGreaterThanOrEqual(stacked.tickets.y + stacked.tickets.height);
  });

  test("lays the floor out kitchen | pass | dining-over-door", () => {
    for (const [width, height] of SIZES) {
      const layout = restaurantArenaLayout(width, height);
      const where = `${width}x${height}`;
      expect(layout.pass.x, where).toBeGreaterThanOrEqual(layout.kitchen.x + layout.kitchen.width);
      expect(layout.dining.x, where).toBeGreaterThanOrEqual(layout.pass.x + layout.pass.width);
      expect(layout.door.y, where).toBeGreaterThanOrEqual(layout.dining.y + layout.dining.height);
      expect(layout.tickets.y, where).toBeGreaterThanOrEqual(layout.door.y + layout.door.height);
      expect(layout.brief.y, where).toBeGreaterThanOrEqual(layout.topBar.y + layout.topBar.height);
      expect(layout.kitchen.y, where).toBeGreaterThanOrEqual(layout.brief.y + layout.brief.height);
    }
  });

  test("keeps the host stand a real click target at any size", () => {
    for (const [width, height] of SIZES) {
      const { doorStand } = restaurantArenaLayout(width, height);
      expect(doorStand.width, `${width}x${height}`).toBeGreaterThanOrEqual(MIN_STAND_WIDTH);
      expect(doorStand.height, `${width}x${height}`).toBeGreaterThanOrEqual(MIN_STAND_HEIGHT);
    }
    // And it grows with the window rather than staying at the floor size.
    expect(restaurantArenaLayout(1600, 1400).doorStand.height).toBeGreaterThan(MIN_STAND_HEIGHT);
  });

  test("runs the hallway line through the pass zone", () => {
    for (const [width, height] of SIZES) {
      const { pass, spineY } = restaurantArenaLayout(width, height);
      const where = `${width}x${height}`;
      expect(spineY, where).toBeGreaterThanOrEqual(pass.y);
      expect(spineY, where).toBeLessThanOrEqual(pass.y + pass.height);
    }
  });

  test("parks staff in their own zones, with the queue on the stand", () => {
    for (const [width, height] of SIZES) {
      const layout = restaurantArenaLayout(width, height);
      const where = `${width}x${height}`;
      const inside = (point: { x: number; y: number }, rect: ArenaRect) =>
        point.x >= rect.x && point.x <= rect.x + rect.width && point.y >= rect.y && point.y <= rect.y + rect.height;

      expect(inside(layout.waypoints.kitchen, layout.kitchen), `kitchen ${where}`).toBe(true);
      expect(inside(layout.waypoints.pass, layout.pass), `pass ${where}`).toBe(true);
      expect(inside(layout.waypoints.floor, layout.dining), `floor ${where}`).toBe(true);
      expect(inside(layout.waypoints.queue, layout.doorStand), `queue ${where}`).toBe(true);
      // Kitchen and pass sit on the hallway, so a kitchen→pass walk is straight.
      expect(layout.waypoints.kitchen.y, where).toBe(layout.spineY);
      expect(layout.waypoints.pass.y, where).toBe(layout.spineY);
    }
  });
});

