import { describe, expect, test } from "bun:test";
import { restaurantArenaLayout } from "./restaurant-arena-layout.js";
import {
  bfsPath,
  corridorPoints,
  hopDurationMs,
  StaffWalker,
  WALK_GRAPH,
  WALK_SPEED_PX_PER_SEC,
  type Point,
  type WalkNode,
} from "./staff-walk.js";

const layout = restaurantArenaLayout(520, 740);
const waypoints = layout.waypoints;
const spineY = layout.spineY;

/** Run a walk to completion, the way the scene's update loop does. */
function walkToRest(walker: StaffWalker, speed = 1, dtMs = 16): number {
  let frames = 0;
  while (walker.walking && frames < 10_000) {
    walker.step(dtMs, speed);
    frames += 1;
  }
  return frames;
}

describe("WALK_GRAPH", () => {
  test("wires the four stations as one hallway", () => {
    expect(WALK_GRAPH.kitchen).toEqual(["pass"]);
    expect(WALK_GRAPH.queue).toEqual(["floor"]);
    expect(new Set(WALK_GRAPH.pass)).toEqual(new Set(["kitchen", "floor"]));
    expect(new Set(WALK_GRAPH.floor)).toEqual(new Set(["pass", "queue"]));
  });

  test("is symmetric — every hallway link works both ways", () => {
    for (const node of Object.keys(WALK_GRAPH) as WalkNode[]) {
      for (const neighbour of WALK_GRAPH[node]) {
        expect(WALK_GRAPH[neighbour]).toContain(node);
      }
    }
  });
});

describe("bfsPath", () => {
  test("routes the kitchen to the door through both through-stations", () => {
    expect(bfsPath("kitchen", "queue")).toEqual(["kitchen", "pass", "floor", "queue"]);
    expect(bfsPath("queue", "kitchen")).toEqual(["queue", "floor", "pass", "kitchen"]);
  });

  test("routes neighbours straight there", () => {
    expect(bfsPath("kitchen", "pass")).toEqual(["kitchen", "pass"]);
    expect(bfsPath("floor", "queue")).toEqual(["floor", "queue"]);
    expect(bfsPath("pass", "queue")).toEqual(["pass", "floor", "queue"]);
  });

  test("staying put is a one-station route", () => {
    expect(bfsPath("pass", "pass")).toEqual(["pass"]);
  });

  test("every pair is reachable, shortest-first", () => {
    const nodes: WalkNode[] = ["kitchen", "pass", "floor", "queue"];
    for (const from of nodes) {
      for (const to of nodes) {
        const path = bfsPath(from, to);
        expect(path[0]).toBe(from);
        expect(path[path.length - 1]).toBe(to);
        for (let i = 1; i < path.length; i++) {
          expect(WALK_GRAPH[path[i - 1]!]).toContain(path[i]!);
        }
      }
    }
  });
});

describe("corridorPoints", () => {
  test("rides the hallway instead of cutting across rooms", () => {
    const start = waypoints.kitchen;
    const points = corridorPoints(start, bfsPath("kitchen", "queue"), waypoints, spineY);
    expect(points.length).toBeGreaterThan(0);
    // Every leg is axis-aligned — no diagonals through walls or tables.
    let previous: Point = start;
    for (const point of points) {
      expect(point.x === previous.x || point.y === previous.y).toBe(true);
      previous = point;
    }
    // And it lands on the destination.
    expect(points[points.length - 1]).toEqual(waypoints.queue);
  });

  test("every horizontal travel happens on the hallway line", () => {
    const start = { x: waypoints.queue.x, y: waypoints.queue.y };
    const points = corridorPoints(start, bfsPath("queue", "kitchen"), waypoints, spineY);
    let previous: Point = start;
    for (const point of points) {
      if (point.x !== previous.x) {
        expect(point.y).toBe(spineY);
        expect(previous.y).toBe(spineY);
      }
      previous = point;
    }
    expect(points.some((point) => point.y === spineY)).toBe(true);
  });

  test("emits no points for a walk that is already there", () => {
    expect(corridorPoints(waypoints.pass, bfsPath("pass", "pass"), waypoints, spineY)).toEqual([]);
    expect(corridorPoints(waypoints.kitchen, [], waypoints, spineY)).toEqual([]);
  });
});

describe("hopDurationMs", () => {
  test("walks at 200px/s", () => {
    expect(hopDurationMs({ x: 0, y: 0 }, { x: WALK_SPEED_PX_PER_SEC, y: 0 })).toBe(1000);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 0, y: 100 })).toBe(500);
    expect(hopDurationMs({ x: 10, y: 10 }, { x: 10, y: 10 })).toBe(0);
  });
});

describe("StaffWalker", () => {
  test("starts parked on its slot", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.y).toBe(waypoints.kitchen.y);
    expect(walker.node).toBe("kitchen");
    expect(walker.walking).toBe(false);
    expect(walker.step(16, 1)).toBe(false);
  });

  test("walks the hallway to a new station and lands on it", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    expect(walker.walking).toBe(true);
    expect(walker.node).toBe("queue");

    const frames = walkToRest(walker);
    expect(frames).toBeGreaterThan(1); // it took time — it did not teleport
    expect(walker.walking).toBe(false);
    expect(walker.x).toBe(waypoints.queue.x);
    expect(walker.y).toBe(waypoints.queue.y);
  });

  test("takes roughly the corridor distance at 200px/s", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    const points = corridorPoints(waypoints.kitchen, bfsPath("kitchen", "queue"), waypoints, spineY);
    let expected = 0;
    let previous: Point = waypoints.kitchen;
    for (const point of points) {
      expected += hopDurationMs(previous, point);
      previous = point;
    }
    walker.setTarget("queue", waypoints, spineY);
    const elapsed = walkToRest(walker, 1, 1);
    expect(elapsed).toBeGreaterThan(expected * 0.9);
    expect(elapsed).toBeLessThan(expected * 1.1 + 4);
  });

  test("a paused clock freezes the walk, and speed makes them hustle", () => {
    const paused = new StaffWalker("kitchen", waypoints.kitchen);
    paused.setTarget("queue", waypoints, spineY);
    expect(paused.step(16, 0)).toBe(false);
    expect(paused.x).toBe(waypoints.kitchen.x);
    expect(paused.y).toBe(waypoints.kitchen.y);
    expect(paused.walking).toBe(true);

    const slow = new StaffWalker("kitchen", waypoints.kitchen);
    const fast = new StaffWalker("kitchen", waypoints.kitchen);
    slow.setTarget("queue", waypoints, spineY);
    fast.setTarget("queue", waypoints, spineY);
    expect(walkToRest(fast, 4)).toBeLessThan(walkToRest(slow, 1));
  });

  test("eases each hop rather than moving at a constant rate", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("pass", waypoints, spineY);
    const firstStep = Math.abs(walker.x - waypoints.kitchen.x);
    walker.step(20, 1);
    const startOfHop = Math.abs(walker.x - waypoints.kitchen.x);
    walker.step(20, 1);
    const middleOfHop = Math.abs(walker.x - waypoints.kitchen.x) - startOfHop;
    void firstStep;
    // Ease-in: the second 20ms covers more ground than the first.
    expect(middleOfHop).toBeGreaterThan(startOfHop);
  });

  test("faces the way it is walking", () => {
    const walker = new StaffWalker("queue", waypoints.queue);
    walker.setTarget("kitchen", waypoints, spineY);
    walkToRest(walker);
    expect(walker.facing).toBe(-1); // the kitchen is stage left
    walker.setTarget("queue", waypoints, spineY);
    walker.step(16, 1);
    walkToRest(walker);
    expect(walker.facing).toBe(1);
  });

  test("a drag owns the position — stepping does not fight it", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.dragging = true;
    walker.x = 11;
    walker.y = 12;
    expect(walker.step(200, 1)).toBe(false);
    expect(walker.x).toBe(11);
    expect(walker.y).toBe(12);
  });

  test("snap drops the walk in place, as a drop does", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.snap({ x: 40, y: 50 }, "pass");
    expect(walker.walking).toBe(false);
    expect(walker.node).toBe("pass");
    expect(walker.x).toBe(40);
    expect(walker.y).toBe(50);
    expect(walker.step(200, 1)).toBe(false);
  });

  test("re-routes from where it actually is when the target changes mid-walk", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(120, 1);
    walker.setTarget("kitchen", waypoints, spineY);
    expect(walker.node).toBe("kitchen");
    walkToRest(walker);
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.y).toBe(waypoints.kitchen.y);
  });

  test("settles onto a shifted slot in the same zone", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    const stacked = { ...waypoints, kitchen: { x: waypoints.kitchen.x + 22, y: waypoints.kitchen.y } };
    walker.setTarget("kitchen", stacked, spineY);
    expect(walker.walking).toBe(true);
    walkToRest(walker);
