import { describe, expect, test } from "bun:test";
import { RepaintGate } from "./restaurant-arena-repaint-gate.js";

describe("RepaintGate", () => {
  test("paints immediately when nothing is being dragged", () => {
    const gate = new RepaintGate();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
    expect(gate.requestPaint()).toBe(true);
    // Nothing was held back, so nothing is owed.
    expect(gate.endDrag()).toBe(false);
  });

  test("holds a paint back for the length of a drag and replays it once", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.isDragging).toBe(true);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.endDrag()).toBe(true);
    expect(gate.isDragging).toBe(false);
    // Exactly one repaint is owed, however many ticks landed during the drag.
    expect(gate.endDrag()).toBe(false);
  });

  test("collapses a whole flurry of held paints into one", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    for (let i = 0; i < 20; i++) expect(gate.requestPaint()).toBe(false);
    expect(gate.endDrag()).toBe(true);
    expect(gate.endDrag()).toBe(false);
  });

  test("owes nothing when a drag passes with no state change", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
  });

  test("paints again as normal once the drag is over", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.endDrag();
    expect(gate.requestPaint()).toBe(true);
  });

  test("a resize drops the drag and forgets what was owed", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.requestPaint()).toBe(false);
    gate.resize();
    expect(gate.isDragging).toBe(false);
    // The resize repainted from scratch, so the stray dragend owes nothing.
    expect(gate.endDrag()).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("a resize with no drag open changes nothing", () => {
    const gate = new RepaintGate();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("a fresh drag after a resize gates paints again", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.resize();
    gate.beginDrag();
    expect(gate.requestPaint()).toBe(false);
    expect(gate.endDrag()).toBe(true);
  });
});

