  });

  test("paints again as normal once the drag is over", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.endDrag();
    expect(gate.requestPaint()).toBe(true);
  });

  test("a resize drops the drag and forgets what was owed", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.requestPaint()).toBe(false);
    gate.resize();
    expect(gate.isDragging).toBe(false);
    // The resize repainted from scratch, so the stray dragend owes nothing.
    expect(gate.endDrag()).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("a resize with no drag open changes nothing", () => {
    const gate = new RepaintGate();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("a fresh drag after a resize gates paints again", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.resize();
    gate.beginDrag();
    expect(gate.requestPaint()).toBe(false);
    expect(gate.endDrag()).toBe(true);
  });
});

