/**
 * Walk the staff. The engine moves a worker between stations instantly —
 * `assign_<role>_<location>` is one atomic action — so this is the only
 * place the *cost* of that move is visible: they leave the line, cross the
 * pass, cross the dining room, and only then are they at the door.
 */
update(_time: number, delta: number): void {
  // A stopped clock stops the floor: a shift frozen for a decision that
  // still has people gliding around it reads as if the pause didn't take.
  const speed = this.running ? Math.max(0, this.state.sim?.speed ?? 1) : 0;
  for (const [role, walker] of this.walkers) {
    const token = this.staffTokens.get(role);
    if (walker.dragging) continue;
    const moved = walker.step(delta, speed);
    if (!token) continue;
    if (moved || walker.walking) {
      this.parked.delete(role);
      this.tweens.killTweensOf(token);
      token.setPosition(walker.x, walker.y);
      const figure = token.getByName("figure");
      if (figure instanceof Phaser.GameObjects.Container) figure.setScale(walker.facing, 1);
      continue;
    }
    // Arrived: hand the token back to the idle bob, once.
    if (!this.parked.has(role)) {
      this.parked.add(role);
      token.setPosition(walker.x, walker.y);
      this.startIdleBob(token, walker.y, role);
    }
  }
}

