private stackedSlot(location: Location, offset: number, layout: RestaurantArenaLayout): { x: number; y: number } {
  const compact = layout.compact;
  const slot = layout.waypoints[location];
  return { x: slot.x + offset * this.px(compact ? 17 : 22), y: slot.y };
}

/**
 * The waypoint set a walker should route against, with `location`'s slot
 * replaced by this particular worker's stacked one — two cooks on the line
 * stand beside each other rather than inside each other, and each has to
 * walk to their *own* spot.
 */
private slotWaypoints(location: Location, slot: Point, layout: RestaurantArenaLayout): Record<Location, Point> {
  return { ...layout.waypoints, [location]: slot };
}

private drawWorkers(layout: RestaurantArenaLayout): void {
  const compact = layout.compact;
  const offsets = new Map<Location, number>();
  this.staffTokens.clear();

  const present = new Set<Role>();
  for (const worker of this.state.workers) {
    const location = this.visualLocation(worker);
    const offset = offsets.get(location) ?? 0;
    offsets.set(location, offset + 1);
    const slot = this.stackedSlot(location, offset, layout);
    present.add(worker.role);

    // A walker that already exists keeps its pixel position across this
    // repaint; only a role appearing for the first time is placed directly
    // on its slot.
    let walker = this.walkers.get(worker.role);
    if (!walker) {
      walker = new StaffWalker(location, slot);
      this.walkers.set(worker.role, walker);
      this.parked.add(worker.role);
    } else if (!walker.dragging) {
      const settled = walker.node === location && !walker.walking;
      const offSlot = Math.hypot(walker.x - slot.x, walker.y - slot.y) > 1;
      // Either the station changed (walk the hallway there) or they are
      // standing away from their slot after a drop or a re-stack (walk the
      // short distance into place).
      if (walker.node !== location || (settled && offSlot)) {
        walker.setTarget(location, this.slotWaypoints(location, slot, layout), layout.spineY);
        this.parked.delete(worker.role);
      }
    }

    const token = this.buildAvatar(walker.x, walker.y, worker.role, worker.load, compact);
    this.staffTokens.set(worker.role, token);
    const figure = token.getByName("figure");
    if (figure instanceof Phaser.GameObjects.Container) figure.setScale(walker.facing, 1);
    const heldHost = worker.role === "host" && Boolean(this.state.seatingHeld) && location === "queue";
    const status = heldHost ? "acting" : (this.workerStatuses.get(worker.role) ?? this.workerStatus(worker));
    this.drawWorkerBadge(token, status, compact, heldHost);
    this.drawSpeechBubble(token, worker.role, compact);
    this.makeDraggable(token, worker.role, walker, location, compact);
  }

  // A role that left the roster (a shift restart with a different crew)
  // shouldn't keep a walker mid-hallway forever.
  for (const role of [...this.walkers.keys()]) {
    if (!present.has(role)) {
      this.walkers.delete(role);
      this.parked.delete(role);
    }
  }
}

// ── Dragging staff between zones ─────────────────────────────────────

/** The station a pixel belongs to, or undefined for the chrome around the floor. */
private zoneAt(x: number, y: number): Location | undefined {
  const inside = (rect: ArenaRect) =>
    x >= rect.x && x <= rect.x + rect.width && y >= rect.y && y <= rect.y + rect.height;
  const layout = this.layout;
  if (inside(layout.kitchen)) return "kitchen";
  if (inside(layout.pass)) return "pass";
  if (inside(layout.dining)) return "floor";
  if (inside(layout.door) || inside(layout.doorStand)) return "queue";
  return undefined;
}

/**
 * Picking a member of staff up and putting them somewhere else is the one
 * move on this floor that isn't a click — it is how the player says "you,
 * over there", and it dispatches the same replayable
 * `assign_<role>_<location>` action the model's own tool call does.
 *
 * The repaint gate is what makes it usable: the shift clock keeps ticking
 * while the token is in the player's hand, and every tick would otherwise
 * repaint the scene out from under the drag.
 */
private makeDraggable(
  token: Phaser.GameObjects.Container,
  role: Role,
  walker: StaffWalker,
  location: Location,
  compact: boolean,
): void {
  const grab = this.px(compact ? 13 : 17);
  token.setInteractive(new Phaser.Geom.Circle(0, 0, grab), Phaser.Geom.Circle.Contains, { draggable: true });
  this.input.setDraggable(token);

  token.on("dragstart", () => {
    this.repaints.beginDrag();
    walker.dragging = true;
    this.parked.delete(role);
    this.tweens.killTweensOf(token);
    token.setDepth(70);
    token.setScale(1.06);
  });

  token.on("drag", (_pointer: Phaser.Input.Pointer, dragX: number, dragY: number) => {
    token.setPosition(dragX, dragY);
    walker.x = dragX;
    walker.y = dragY;
  });

  token.on("dragend", () => {
    walker.dragging = false;
    token.setDepth(20);
    token.setScale(1);

    const dropped = this.zoneAt(token.x, token.y);
    const target = dropped ?? location;
    // Land them where the pointer left them, then let them walk to the
    // proper slot from there — routing from the zone they were dropped in,
    // not the one they were dragged out of.
    walker.snap({ x: token.x, y: token.y }, dropped ?? walker.node);
    walker.setTarget(target, this.slotWaypoints(target, this.stackedSlot(target, 0, this.layout), this.layout), this.layout.spineY);

    const reassigned = dropped !== undefined && dropped !== location;
    if (reassigned) this.onAction(`assign_${role}_${dropped}`);
    // One repaint at most: whatever the clock (or the assignment above)
    // asked for while the token was in hand, replayed now that it isn't.
    if (this.repaints.endDrag() || !reassigned) this.paint();
  });
}

