645	    const zone = layout.kitchen;
646	    const compact = layout.compact;
647	    this.zonePanel(g, zone, COLORS.kitchen, "KITCHEN", compact);
648	
649	    const pad = compact ? 5 : 8;
650	    const top = zone.y + (compact ? 15 : 20);
651	    const oven = this.state.equipment.find((item) => item.kind === "oven");
652	    const stock = Object.values(this.state.inventory).reduce((sum, count) => sum + count, 0);
653	    const stations: Array<{ label: string; sub: string; color: number; action?: string; tip?: string; dim?: boolean }> = [
654	      { label: "PREP", sub: "", color: 0xf1e6c8 },
655	      { label: "PANTRY", sub: `${stock} left`, color: 0xd4b483 },
656	      {
657	        label: "OVEN",
658	        sub: oven?.status === "failed" ? "DEAD — CLICK" : oven?.status === "degraded" ? "limping" : "ready",
659	        color: oven?.status === "failed" ? COLORS.failed : oven?.status === "degraded" ? 0xd6892f : COLORS.working,
660	        action: oven?.status === "failed" ? "inspect_oven" : undefined,
661	        tip: oven?.status === "failed" ? "Fix the oven" : undefined,
662	      },
663	    ];
664	    // The one in-shift purchase on offer — a permanent second pair of hands
665	    // at the stations, paid for out of tonight's own takings. Affordable
666	    // once cash clears the cost; a one-time click, not a recurring cost.
667	    const upgrade = this.state.upgrade;
668	    if (upgrade) {
669	      const affordable = this.state.outcomes.cash >= upgrade.cost;
670	      stations.push(
671	        upgrade.bought
672	          ? { label: upgrade.label.toUpperCase(), sub: "installed", color: 0x8fbfa0 }
673	          : {
674	              label: `+${upgrade.label.toUpperCase()}`,
675	              sub: `$${upgrade.cost} — click`,
676	              color: affordable ? COLORS.pass : 0x5c4a3a,
677	              action: affordable ? "buy_second_stove" : undefined,
678	              tip: affordable ? "Second pair of hands, all shift" : `Need $${upgrade.cost} to install`,
679	              dim: !affordable,
680	            },
681	      );
682	    }
683	
684	    // On a real desktop window this zone can run far taller than these
685	    // cards need — capped height plus vertical centering keeps them a
686	    // sensible size instead of stretching into empty slabs.
687	    const rawStationHeight = (zone.height - (top - zone.y) - pad * (stations.length + 1)) / stations.length;
688	    const stationHeight = Math.min(compact ? 40 : 76, Math.max(14, rawStationHeight));
689	    const groupHeight = stationHeight * stations.length + pad * (stations.length - 1);
690	    const groupTop = top + Math.max(0, (zone.height - (top - zone.y) - groupHeight) / 2);
691	
692	    stations.forEach((station, index) => {
693	      const y = groupTop + index * (stationHeight + pad);
