722	  private drawPass(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
723	    const zone = layout.pass;
724	    this.zonePanel(g, zone, COLORS.pass, "PASS", layout.compact, true);
725	    this.hotspot(zone, "verify_substitution", "Verify the ticket");
726	    const y = zone.y + zone.height * 0.6;
727	    g.fillStyle(0x7b4c2e);
728	    g.fillRoundedRect(zone.x + 3, y, zone.width - 6, layout.compact ? 12 : 18, 3);
729	    // Plates waiting on the pass = orders cooked but not yet run to a table.
730	    const ready = this.state.orders.filter((order) => order.status === "ready").length;
731	    for (let i = 0; i < Math.min(3, ready); i++) {
732	      g.fillStyle(0xfff3d6);
733	      g.fillCircle(zone.x + zone.width / 2, y + 4 + i * (layout.compact ? 5 : 7), layout.compact ? 2.5 : 3.5);
734	    }
735	    if (ready > 0) {
736	      this.add
737	        .text(zone.x + zone.width / 2, zone.y + zone.height - 4, `${ready}`, {
738	          color: "#2b2118",
739	          fontFamily: MONO,
