747	  private drawDining(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
748	    const zone = layout.dining;
749	    const compact = layout.compact;
750	    this.zonePanel(g, zone, COLORS.dining, "DINING", compact);
751	
752	    const tables = this.state.tables.slice(0, 4);
753	    const top = zone.y + (compact ? 15 : 19);
754	    const available = Math.max(24, zone.height - (top - zone.y) - 4);
755	    const cols = tables.length > 2 ? 2 : tables.length || 1;
756	    const rows = Math.ceil(tables.length / cols) || 1;
757	
758	    tables.forEach((table, index) => {
759	      const col = index % cols;
760	      const row = Math.floor(index / cols);
761	      const cx = zone.x + (zone.width * (col + 0.5)) / cols;
762	      const cy = top + (available * (row + 0.5)) / rows;
763	      // Capped at a fixed 18px, tables read as a sparse handful of dots on a
764	      // real desktop window where this zone is much bigger than a 520px
765	      // canvas — let them grow with the room, not just with the cell they
766	      // have to fit in.
767	      const fitsCell = Math.min(zone.width / cols, available / rows) * 0.3;
768	      const styleCap = compact ? 13 : Math.min(32, 18 + Math.max(0, zone.width - 360) * 0.03);
769	      const radius = Math.max(8, Math.min(styleCap, fitsCell));
