 */
private drawOutcomeToast(compact: boolean, width: number, height: number): void {
  const toast = this.outcomeToast;
  if (!toast) return;
  const elapsed = Date.now() - toast.startedAt;
  if (elapsed >= this.outcomeToastMs) {
