/**
 * Picking a member of staff up and putting them somewhere else is the one
 * move on this floor that isn't a click — it is how the player says "you,
 * over there", and it dispatches the same replayable
 * `assign_<role>_<location>` action the model's own tool call does.
 *
 * The repaint gate is what makes it usable: the shift clock keeps ticking
 * while the token is in the player's hand, and every tick would otherwise
 * repaint the scene out from under the drag.
 */
private makeDraggable(
  token: Phaser.GameObjects.Container,
  role: Role,
  walker: StaffWalker,
  location: Location,
  compact: boolean,
): void {
  const grab = this.px(compact ? 13 : 17);
  token.setInteractive(new Phaser.Geom.Circle(0, 0, grab), Phaser.Geom.Circle.Contains, { draggable: true });
  this.input.setDraggable(token);

  token.on("dragstart", () => {
    this.repaints.beginDrag();
    walker.dragging = true;
    this.parked.delete(role);
    this.tweens.killTweensOf(token);
    token.setDepth(70);
    token.setScale(1.06);
