 *
 * The repaint gate is what makes it usable: the shift clock keeps ticking
 * while the token is in the player's hand, and every tick would otherwise
 * repaint the scene out from under the drag.
 */
private makeDraggable(
  token: Phaser.GameObjects.Container,
  role: Role,
  walker: StaffWalker,
  location: Location,
  compact: boolean,
): void {
  // A container has no size of its own, so the grab area is explicit: a disc
  // over the figure, which grows with the window like the figure does.
  const grab = this.px(compact ? 13 : 17);
  token.setInteractive({
    hitArea: new Phaser.Geom.Circle(0, 0, grab),
    hitAreaCallback: Phaser.Geom.Circle.Contains,
    draggable: true,
    useHandCursor: true,
  });

  token.on("dragstart", () => {
    this.repaints.beginDrag();
    walker.dragging = true;
    this.parked.delete(role);
    this.tweens.killTweensOf(token);
    token.setDepth(70);
    token.setScale(1.06);
  });

  token.on("drag", (_pointer: Phaser.Input.Pointer, dragX: number, dragY: number) => {
    token.setPosition(dragX, dragY);
    walker.x = dragX;
    walker.y = dragY;
  });

  token.on("dragend", () => {
    walker.dragging = false;
    token.setDepth(20);
    token.setScale(1);

    // Land them where the pointer let go, keeping the zone they were
    // dropped in as the station they route *from* — a cook dropped in the
    // dining room walks to their table from there, not back out through the
    // pass they were dragged across. The repaint below settles them onto the
    // proper slot; see `drawWorkers`.
    const dropped = this.zoneAt(token.x, token.y);
    walker.snap({ x: token.x, y: token.y }, dropped ?? walker.node);

    // The assignment goes in while the gate is still shut, so the state
    // update it triggers is held and folded into the single paint below
    // instead of yanking the token away first.
    if (dropped !== undefined && dropped !== location) this.onAction(`assign_${role}_${dropped}`);
    this.repaints.endDrag();
    this.paint();
  });
}

